/** Bounded, uncompressed ZIP writer. Filenames are generated by the service, not user paths. */
export const MAX_EXPORT_BYTES = 12 * 1024 * 1024;
export class ExportUnavailable extends Error {}
export interface ExportEntry { name: string; bytes: Buffer }

function crc32(bytes: Buffer): number {
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit++) crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

export function createPrivateArchive(entries: ExportEntry[]): Buffer {
  if (entries.length > 5000) throw new ExportUnavailable("Too many files for an immediate export. Request a full export from the privacy team.");
  const local: Buffer[] = [];
  const central: Buffer[] = [];
  const names = new Set<string>();
  let offset = 0;
  for (const entry of entries) {
    if (!/^[a-zA-Z0-9_./-]+$/.test(entry.name) || entry.name.startsWith("/") || entry.name.split("/").includes("..") || names.has(entry.name)) {
      throw new ExportUnavailable("An archive filename failed validation.");
    }
    names.add(entry.name);
    const name = Buffer.from(entry.name, "utf8");
    const header = Buffer.alloc(30);
    header.writeUInt32LE(0x04034b50);
    header.writeUInt16LE(20, 4);
    header.writeUInt16LE(0x800, 6); // UTF-8, no compression.
    header.writeUInt16LE(33, 12); // 1980-01-01
    header.writeUInt32LE(crc32(entry.bytes), 14);
    header.writeUInt32LE(entry.bytes.length, 18);
    header.writeUInt32LE(entry.bytes.length, 22);
    header.writeUInt16LE(name.length, 26);
    const directory = Buffer.alloc(46);
    directory.writeUInt32LE(0x02014b50);
    directory.writeUInt16LE(20, 4);
    header.copy(directory, 6, 4, 28);
    directory.writeUInt32LE(offset, 42);
    local.push(header, name, entry.bytes);
    central.push(directory, name);
    offset += header.length + name.length + entry.bytes.length;
    if (offset > MAX_EXPORT_BYTES) throw new ExportUnavailable("The archive exceeds the 12 MB immediate-download limit. Request a full export from the privacy team.");
  }
  const size = central.reduce((total, bytes) => total + bytes.length, 0);
  if (offset + size + 22 > MAX_EXPORT_BYTES) throw new ExportUnavailable("The archive exceeds the immediate-download limit.");
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50);
  end.writeUInt16LE(entries.length, 8);
  end.writeUInt16LE(entries.length, 10);
  end.writeUInt32LE(size, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...local, ...central, end]);
}
